function canReachCorner(xCorner, yCorner, circles) {
  const n = circles.length;
  const X = BigInt(xCorner);
  const Y = BigInt(yCorner);
  const xs = circles.map(circle => BigInt(circle[0]));
  const ys = circles.map(circle => BigInt(circle[1]));
  const rs = circles.map(circle => BigInt(circle[2]));
  const parent = Array.from({ length: n + 2 }, (_, i) => i);
  const find = node => {
    while (parent[node] !== node) {
      parent[node] = parent[parent[node]];
      node = parent[node];
    }
    return node;
  };
  const union = (a, b) => {
    parent[find(a)] = find(b);
  };
  const within = (x, y, r, px, py) => (x - px) * (x - px) + (y - py) * (y - py) <= r * r;
  const TOP_LEFT = n;
  const BOTTOM_RIGHT = n + 1;
  for (let i = 0; i < n; i++) {
    const x = xs[i];
    const y = ys[i];
    const r = rs[i];
    if (within(x, y, r, 0n, 0n) || within(x, y, r, X, Y)) {
      return false;
    }
    if ((x <= X && y - r <= Y && Y <= y + r) || (y <= Y && x <= r)) {
      union(i, TOP_LEFT);
    }
    if ((y <= Y && x - r <= X && X <= x + r) || (x <= X && y <= r)) {
      union(i, BOTTOM_RIGHT);
    }
    for (let j = 0; j < i; j++) {
      const x2 = xs[j];
      const y2 = ys[j];
      const r2 = rs[j];
      if (find(i) === find(j) || !within(x, y, r + r2, x2, y2)) {
        continue;
      }
      if (x * r2 + x2 * r < (r + r2) * X && y * r2 + y2 * r < (r + r2) * Y) {
        union(i, j);
      }
    }
  }
  return find(TOP_LEFT) !== find(BOTTOM_RIGHT);
}

