function canReachCorner(xCorner, yCorner, circles) {
  // Breadth-first search over the circles. A circle starts a wall when its disc meets the top or the left side,
  // ends one when it meets the bottom or the right side, and two circles are linked when their discs share a
  // point of the closed rectangle. Everything is decided exactly with integers.
  const X = BigInt(xCorner), Y = BigInt(yCorner);
  const discs = circles.map(c => c.map(v => BigInt(v)));
  const sq = v => v * v;
  const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);
  const contains = ([x, y, r], px, py) => sq(x - px) + sq(y - py) <= sq(r);
  // The nearest point of an axis-parallel segment is the centre clamped onto it.
  const meetsSegment = ([x, y, r], ax, ay, bx, by) => sq(x - clamp(x, ax, bx)) + sq(y - clamp(y, ay, by)) <= sq(r);
  for (const d of discs) if (contains(d, 0n, 0n) || contains(d, X, Y)) return false;
  const startsWall = d => meetsSegment(d, 0n, Y, X, Y) || meetsSegment(d, 0n, 0n, 0n, Y);
  const endsWall = d => meetsSegment(d, 0n, 0n, X, 0n) || meetsSegment(d, X, 0n, X, Y);
  // v <= sqrt(p), and v <= sqrt(p) + sqrt(q), for p, q >= 0, without square roots.
  const atMostRoot = (v, p) => v <= 0n || sq(v) <= p;
  const atMostRootSum = (v, p, q) => {
    if (v <= 0n) return true;
    const t = sq(v) - p - q;
    return t <= 0n || sq(t) <= 4n * p * q;
  };
  // Do both discs meet a common point of one side? Each disc cuts the side's line in an interval
  // [centre - sqrt(p), centre + sqrt(p)]; three intervals on a line share a point when every two of them do.
  const shareSidePoint = (a, b, horizontal, level, length) => {
    const chord = ([x, y, r]) => {
      const along = horizontal ? x : y, across = horizontal ? y : x;
      const p = sq(r) - sq(across - level);
      return p < 0n ? null : [along, p];
    };
    const ca = chord(a), cb = chord(b);
    if (!ca || !cb) return false;
    const [u, p] = ca, [v, q] = cb;
    return atMostRootSum(u - v, p, q) && atMostRootSum(v - u, q, p) && atMostRoot(u - length, p) && atMostRoot(-u, p) && atMostRoot(v - length, q) && atMostRoot(-v, q);
  };
  // A point inside both discs: a centre that the other disc contains, otherwise the middle of their
  // common chord. It is returned as integer numerators over a common denominator.
  const commonPoint = (a, b) => {
    const [x1, y1, r1] = a, [x2, y2, r2] = b;
    if (contains(a, x2, y2)) return [x2, y2, 1n];
    if (contains(b, x1, y1)) return [x1, y1, 1n];
    const d2 = sq(x2 - x1) + sq(y2 - y1), num = d2 + sq(r1) - sq(r2), den = 2n * d2;
    return [x1 * den + (x2 - x1) * num, y1 * den + (y2 - y1) * num, den];
  };
  const linked = (a, b) => {
    if (sq(a[0] - b[0]) + sq(a[1] - b[1]) > sq(a[2] + b[2])) return false;
    const [px, py, den] = commonPoint(a, b);
    if (px >= 0n && py >= 0n && px <= X * den && py <= Y * den) return true;
    // The overlap is connected and has a point outside the rectangle, so it meets the rectangle only if it crosses a side.
    return shareSidePoint(a, b, true, 0n, X) || shareSidePoint(a, b, true, Y, X) || shareSidePoint(a, b, false, 0n, Y) || shareSidePoint(a, b, false, X, Y);
  };
  const seen = discs.map(() => false);
  for (let s = 0; s < discs.length; s++) {
    if (seen[s] || !startsWall(discs[s])) continue;
    seen[s] = true;
    const queue = [s];
    while (queue.length) {
      const i = queue.shift();
      if (endsWall(discs[i])) return false;
      for (let j = 0; j < discs.length; j++) {
        if (!seen[j] && linked(discs[i], discs[j])) {
          seen[j] = true;
          queue.push(j);
        }
      }
    }
  }
  return true;
}

