function generate(rand, size) {
  const int = (lo, hi) => Math.floor(lo) + Math.floor(rand() * (Math.floor(hi) - Math.floor(lo) + 1));
  const LIMIT = 1000000000;
  const clampValue = v => Math.max(1, Math.min(LIMIT, Math.round(v)));
  // Approximate test (doubles) used only to steer the shapes away from trivially blocked corners.
  const covers = (c, px, py) => (c[0] - px) ** 2 + (c[1] - py) ** 2 <= c[2] ** 2;
  if (size === 'large') {
    const X = int(500000000, LIMIT), Y = int(500000000, LIMIT);
    const n = int(800, 1000);
    const shape = int(0, 2);
    const circles = [];
    const free = c => !covers(c, 0, 0) && !covers(c, X, Y);
    if (shape === 1) {
      // A wall of overlapping circles from the top or left side to the bottom or right side.
      const from = rand() < 0.5 ? [0, int(1, Y)] : [int(1, X), Y];
      const to = rand() < 0.5 ? [int(1, X), 0] : [X, int(1, Y)];
      const steps = 200;
      const radius = Math.ceil(Math.hypot(to[0] - from[0], to[1] - from[1]) / steps);
      for (let k = 0; k <= steps; k++) {
        const c = [clampValue(from[0] + (to[0] - from[0]) * k / steps), clampValue(from[1] + (to[1] - from[1]) * k / steps), clampValue(radius)];
        if (free(c)) circles.push(c);
      }
    }
    if (shape === 2) {
      // Big circles above and to the right of the rectangle that only dip into it and overlap one another outside it.
      while (circles.length < n / 2) {
        const r = int(X / 20, X / 5);
        const c = rand() < 0.5 ? [int(1, X), clampValue(Y + r - int(0, r / 50)), r] : [clampValue(X + r - int(0, r / 50)), int(1, Y), r];
        if (free(c)) circles.push(c);
      }
    }
    const scale = shape === 0 ? Math.min(X, Y) / 25 : Math.min(X, Y) / 200;
    while (circles.length < n) {
      const c = [int(1, X), int(1, Y), int(1, scale)];
      if (free(c)) circles.push(c);
    }
    return [X, Y, circles];
  }
  const X = int(3, 8), Y = int(3, 8);
  const n = int(1, 5);
  const shape = int(0, 3);
  const circles = [];
  if (shape === 3) {
    // A chain of circles along a line from the top or left side towards the bottom or right side.
    const from = rand() < 0.5 ? [1, int(1, Y)] : [int(1, X), Y];
    const to = rand() < 0.5 ? [int(1, X), 1] : [X, int(1, Y)];
    const r = int(1, 2);
    for (let k = 0; k < n; k++) {
      const t = n === 1 ? 0.5 : k / (n - 1);
      circles.push([clampValue(from[0] + (to[0] - from[0]) * t), clampValue(from[1] + (to[1] - from[1]) * t), r]);
    }
    return [X, Y, circles];
  }
  // Most inputs keep both corners clear, so that walls rather than corners decide the answer.
  const clear = rand() < 0.85;
  while (circles.length < n) {
    const c = shape === 0 ? [int(1, X + 2), int(1, Y + 2), int(1, 3)]
      : shape === 1 ? (rand() < 0.5 ? [int(1, X + 1), int(Y, Y + 6), int(1, 6)] : [int(X, X + 6), int(1, Y + 1), int(1, 6)])
      : [int(1, X), int(1, Y), int(1, 2)];
    if (!clear || (!covers(c, 0, 0) && !covers(c, X, Y))) circles.push(c);
  }
  return [X, Y, circles];
}
